+
+import QtQuick
+import QtQuick.Layouts
+
+import org.kde.kcmutils // KCMLauncher
+import org.kde.config as KConfig  // KAuthorized.authorizeControlModule
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.kirigami as Kirigami
+
+import org.kde.plasma.private.brightnesscontrolplugin
+
+PlasmaComponents3.ItemDelegate {
+    id: root
+
+    required property ColorBlindnessCorrectionControl colorBlindnessCorrectionControl
+
+    background.visible: highlighted
+    highlighted: activeFocus
+    hoverEnabled: false
+
+    visible: colorBlindnessCorrectionControl.configured || colorBlindnessCorrectionControl.active
+
+    Accessible.onPressAction: correctionSwitch.click()
+    Keys.onSpacePressed: correctionSwitch.click()
+    KeyNavigation.tab: kcmButton
+    KeyNavigation.right: kcmButton
+
+    contentItem: RowLayout {
+        spacing: Kirigami.Units.gridUnit
+
+        Kirigami.Icon {
+            id: image
+            Layout.alignment: Qt.AlignTop
+            Layout.preferredWidth: Kirigami.Units.iconSizes.medium
+            Layout.preferredHeight: Kirigami.Units.iconSizes.medium
+            source: "preferences-desktop-accessibility"
+        }
+
+        ColumnLayout {
+            Layout.fillWidth: true
+            Layout.alignment: Qt.AlignTop
+            spacing: Kirigami.Units.smallSpacing
+
+            PlasmaComponents3.Label {
+                id: title
+                text: root.text
+                textFormat: Text.PlainText
+
+                elide: Text.ElideRight
+                Layout.fillWidth: true
+            }
+
+            RowLayout {
+                spacing: Kirigami.Units.smallSpacing
+
+                PlasmaComponents3.Switch {
+                    id: correctionSwitch
+                    Layout.fillWidth: true
+                    activeFocusOnTab: false
+                    focusPolicy: Qt.NoFocus
+                    text: i18nc("@option:check", "Correct colors")
+                    checked: root.colorBlindnessCorrectionControl.active
+                    onClicked: root.colorBlindnessCorrectionControl.active = checked
+                }
+
+                PlasmaComponents3.Button {
+                    id: kcmButton
+                    visible: KConfig.KAuthorized.authorizeControlModule("kcm_access")
+
+                    icon.name: "configure"
+                    text: i18n("Configure…")
+
+                    Layout.alignment: Qt.AlignRight
+
+                    KeyNavigation.up: root.KeyNavigation.up
+
+                    Keys.onPressed: (event) => {
+                        if (event.key == Qt.Key_Space || event.key == Qt.Key_Return || event.key == Qt.Key_Enter) {
+                            animateClick();
+                            event.accepted = true
+                        }
+                    }
+                    onClicked: KCMLauncher.openSystemSettings("kcm_access")
+                }
+            }
+        }
+    }
+}
