+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "colorblindnesscorrectioncontrol.h"
+
+#include <brightnesscontrolplugin_debug.h>
+
+#include <QDBusConnection>
+#include <QDBusMessage>
+#include <QDBusPendingCall>
+#include <QDBusPendingCallWatcher>
+#include <QDBusReply>
+
+#include <KConfigGroup>
+
+using namespace Qt::StringLiterals;
+
+namespace
+{
+inline constexpr QLatin1String KWIN_SERVICE("org.kde.KWin");
+inline constexpr QLatin1String KWIN_EFFECTS_PATH("/Effects");
+inline constexpr QLatin1String KWIN_EFFECTS_INTERFACE("org.kde.kwin.Effects");
+inline constexpr QLatin1String EFFECT_NAME("colorblindnesscorrection");
+}
+
+ColorBlindnessCorrectionControl::ColorBlindnessCorrectionControl(QObject *parent)
+    : QObject(parent)
+    , m_kwinConfig(KSharedConfig::openConfig(u"kwinrc"_s, KConfig::NoGlobals))
+{
+    refresh();
+}
+
+ColorBlindnessCorrectionControl::~ColorBlindnessCorrectionControl()
+{
+}
+
+bool ColorBlindnessCorrectionControl::isConfigured() const
+{
+    return m_configured.value();
+}
+
+QBindable<bool> ColorBlindnessCorrectionControl::bindableConfigured()
+{
+    return &m_configured;
+}
+
+bool ColorBlindnessCorrectionControl::isActive() const
+{
+    return m_active.value();
+}
+
+QBindable<bool> ColorBlindnessCorrectionControl::bindableActive()
+{
+    return &m_active;
+}
+
+void ColorBlindnessCorrectionControl::refresh()
+{
+    m_kwinConfig->reparseConfiguration();
+    m_configured = m_kwinConfig->group(u"Plugins"_s).readEntry("colorblindnesscorrectionEnabled", false);
+
+    QDBusMessage msg = QDBusMessage::createMethodCall(KWIN_SERVICE, KWIN_EFFECTS_PATH, KWIN_EFFECTS_INTERFACE, u"isEffectLoaded"_s);
+    msg << EFFECT_NAME;
+    QDBusPendingCall call = QDBusConnection::sessionBus().asyncCall(msg);
+    auto watcher = new QDBusPendingCallWatcher(call, this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        QDBusReply<bool> reply = *watcher;
+        if (!reply.isValid()) {
+            qCWarning(APPLETS::BRIGHTNESS) << "error querying colorblindness correction effect via dbus:" << reply.error().message();
+            return;
+        }
+        m_active = reply.value();
+    });
+}
+
+void ColorBlindnessCorrectionControl::setActive(bool active)
+{
+    if (m_active.value() == active) {
+        return;
+    }
+
+    // Only (un)load the effect for the current session, so it comes back as configured on next login
+    QDBusMessage msg = QDBusMessage::createMethodCall(KWIN_SERVICE, KWIN_EFFECTS_PATH, KWIN_EFFECTS_INTERFACE, active ? u"loadEffect"_s : u"unloadEffect"_s);
+    msg << EFFECT_NAME;
+    QDBusPendingCall call = QDBusConnection::sessionBus().asyncCall(msg);
+    auto watcher = new QDBusPendingCallWatcher(call, this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, wasActive = m_active.value()](QDBusPendingCallWatcher *watcher) {
+        watcher->deleteLater();
+        if (!watcher->isError()) {
+            return;
+        }
+        qCWarning(APPLETS::BRIGHTNESS) << "error toggling colorblindness correction effect via dbus:" << watcher->error().message();
+        m_active = wasActive;
+    });
+
+    m_active = active;
+}
+
+#include "moc_colorblindnesscorrectioncontrol.cpp"
