+/*
+ * SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#pragma once
+
+#include <QBindable>
+#include <QObject>
+#include <qqmlregistration.h>
+
+#include <KSharedConfig>
+
+class ColorBlindnessCorrectionControl : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    Q_PROPERTY(bool configured READ isConfigured NOTIFY configuredChanged BINDABLE bindableConfigured FINAL)
+    Q_PROPERTY(bool active READ isActive WRITE setActive NOTIFY activeChanged BINDABLE bindableActive FINAL)
+
+public:
+    explicit ColorBlindnessCorrectionControl(QObject *parent = nullptr);
+    ~ColorBlindnessCorrectionControl() override;
+
+    bool isConfigured() const;
+    QBindable<bool> bindableConfigured();
+
+    bool isActive() const;
+    void setActive(bool active);
+    QBindable<bool> bindableActive();
+
+    Q_INVOKABLE void refresh();
+
+Q_SIGNALS:
+    void configuredChanged();
+    void activeChanged();
+
+private:
+    KSharedConfig::Ptr m_kwinConfig;
+    Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(ColorBlindnessCorrectionControl, bool, m_configured, false, &ColorBlindnessCorrectionControl::configuredChanged)
+    Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(ColorBlindnessCorrectionControl, bool, m_active, false, &ColorBlindnessCorrectionControl::activeChanged)
+};
